pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash, uint8 advance) public {
        vm.assume(advance > 0 && advance <= 10);
        address actor = address(0x1000);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash);
        vm.roll(block.number + advance);
        vm.prank(actor);
        bool ok = true;
        try c.settle() { ok = true; } catch { ok = false; }
        // After lockInGuess stores block+1, settle must succeed only after block.number > stored block.
        // Stored = lockBlock + 1, current = lockBlock + advance.
        // Settle succeeds iff advance > 1.
        // For advance==1, reference reverts (true for bug?), for advance>1 reference succeeds.
        // Bug stores lockBlock+2, so needs advance>2 to succeed; fails when advance==2.
        // Universal rule: settle succeeds exactly when advance > locked_blocks_increment.
        // But locked_blocks_increment is private. Instead check: advance > 1 <=> ok.
        // This holds for reference (increment=1), fails for bug (increment=2) when advance=2.
        assertTrue((advance > 1) == ok);
    }
}

