import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 fuzzBlockOffset, uint8 fuzzHashByte) public {
        // Bound to keep block offset positive and less than 256 blocks in the future
        fuzzBlockOffset = bound(fuzzBlockOffset, 1, 255);
        bytes32 hash = bytes32(uint256(fuzzHashByte) * (1 + uint256(keccak256(abi.encode(fuzzBlockOffset)))));
        address actor = address(uint160(uint256(keccak256(abi.encode(fuzzBlockOffset, fuzzHashByte)))));

        // Setup actor with enough ETH for lockInGuess
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash);

        // Warp to the recorded block + 1 (or block.number + 1 + offset in general)
        uint256 recordedBlock = c.guesses(actor).block;
        if (recordedBlock == 0) {
            // Buggy case: no block set, so settle precondition block!=0 will revert anyway
            bool ok;
            try c.settle() {
                ok = true;
            } catch {
                ok = false;
            }
            assertTrue(!ok);
        } else {
            vm.roll(recordedBlock + 1);
            // Settle should succeed if correct
            bool ok;
            try c.settle() {
                ok = true;
            } catch {
                ok = false;
            }
            assertTrue(ok);
        }
    }
}

