        vm.assume(guessBlock > 0);
        vm.assume(guessBlock <= 10);

        vm.deal(actor, 2 ether);
        vm.startPrank(actor);
        c.lockInGuess{value: 1 ether}(hash);
        vm.stopPrank();

        // roll the chain to a block number equal to the stored guess block (block.number == guessBlock)
        // This ensures block.number is NOT strictly greater than the guess block
        // block.number is at least 1 after setUp, so roll to guessBlock
        vm.roll(guessBlock);

        bool ok;
        vm.startPrank(actor);
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // The invariant: settle must revert when called at a block number that is not greater than the stored guess block.
        // In correct contract, block.number > guesses.block is false, so it reverts (ok == false).
        // Buggy contract only requires block.number > 0, which is always true, so it does not revert (ok == true).
        assertTrue(!ok);
    }
}

