pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash, uint256 rollAhead) public {
        // Ensure sufficient balance for lockInGuess and settle payout
        vm.deal(address(this), 2 ether);
        // Deposit 1 ether to constructor via a call with value
        // Constructor requires 1 ether, use a payable deploy or fund the contract directly
        // Since setUp already deploys c with no value, we need to initialize with lockInGuess
        // But first, fund c with 1 ether for constructor? Actually constructor is called in setUp with no value, which fails.
        // Re-deploy c with value to satisfy constructor requirement
        c = new C{value: 1 ether}();

        // Fuzz the guess hash
        // Use vm.prank to lock in guess from some address
        address actor = address(0x12345);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash);

        // Advancing blocks by a fuzzed amount (0 to some range)
        // Correct behavior: settle must revert if called before the guess block + 1
        // Bug: settle allows if block.number > 0, so it never reverts.
        // We test that after lockInGuess, settle called in the same or earlier block reverts.
        // If rollAhead is 0 (no block advancement), correct must revert, buggy succeeds.
        // The fuzzer will find a rollAhead = 0 that causes failure.
        vm.roll(block.number + rollAhead);

        // Try settle
        vm.prank(actor);
        (bool ok,) = address(c).call(abi.encodeWithSelector(c.settle.selector));

        // Assert: settle should not have succeeded if block.number <= guess block
        // For rollAhead = 0, block.number == original block + 0 = guess block (since guess block = block.number + 1 at lock time)
        // Actually lockInGuess sets guess.block = block.number + 1, so we need block.number > that.
        // After vm.roll(block.number + rollAhead), the current block is original + rollAhead.
        // Condition for correct success: original + rollAhead > original + 1 => rollAhead > 1.
        // For rollAhead <= 1, correct must revert.
        // The bug allows success for any rollAhead >= 0 because block.number > 0 is always true.
        // So the property: if rollAhead <= 1, settle must revert.
        bool revertExpected = (rollAhead <= 1);
        assertTrue(revertExpected ? !ok : ok);
    }
}

