pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 unlockBlockDelay, bytes32 guessHash) public {
        // admissible: delay must give a block number > current when settle is called
        vm.assume(unlockBlockDelay > 0);
        uint currentBlock = block.number;
        uint guessBlock = currentBlock + uint(unlockBlockDelay);
        // make sure guessBlock is not too far in the future (blockhash only available for last 256 blocks)
        vm.assume(guessBlock <= currentBlock + 256);

        address caller = address(0x1234);
        // fund caller
        vm.deal(caller, 5 ether);

        // fund contract with 2 ether for potential payout
        vm.deal(address(c), 2 ether);

        // lock in a guess using a block number in the future
        vm.prank(caller);
        c.lockInGuess{value: 1 ether}(guessHash);

        // advance blocks to the guess block and two more so settle can see its blockhash
        vm.roll(guessBlock + 2);

        uint balBefore = address(c).balance;
        uint callerBalBefore = caller.balance;

        vm.prank(caller);
        c.settle();

        uint balAfter = address(c).balance;
        uint callerBalAfter = caller.balance;

        // After settle, the contract balance should equal (balBefore - 2 ether) if guess matches,
        // else (balBefore). The original uses blockhash(guessBlock) and the mutant uses blockhash(block.number),
        // which differ so the payout condition leads to a different balance.
        // The universal property: after settle, the contract balance never exceeds balBefore.
        // The mutant can violate this by paying out when it should not.
        assertTrue(balAfter <= balBefore);
    }
}

