        c.lockInGuess{value: 1 ether}(guess);
        vm.roll(block.number + 2);
        uint256 balBefore = address(c).balance;
        // Settle
        vm.prank(actor);
        bool success;
        try c.settle() { success = true; } catch { success = false; }
        uint256 balAfter = address(c).balance;
        // Property: if settle succeeded, balance decreased by 2 ether (payout) or remains same
        assertTrue(!success || balAfter == balBefore - 2 ether || balAfter == balBefore);
    }
}

