        c.lockInGuess{value: 1 ether}(guessHash);

        // advance at least one block past the locked block so settle() will pass the block.number check
        uint256 settleBlock = block.number + 2;
        vm.roll(settleBlock);

        // record contract balance before settle
        uint256 balBefore = address(c).balance;
        vm.prank(player);
        try c.settle() { /* settle may or may not transfer */ } catch { }
        uint256 balAfter = address(c).balance;

        // retrieve the player's locked block number from public getter
        // struct getter returns (uint block, bytes32 guess) so we call guesses(player)
        // but guesses is mapping(address => Guess) and compiles to guesses(address) returning (uint,bytes32)
        (uint256 lockedBlock,) = c.guesses(player);

        // compute the expected answer as per reference logic:
        // answer = keccak256(abi.encodePacked(blockhash(lockedBlock)))
