        // so when guessHash == refAnswer the buggy settle() will NOT match and will NOT pay,
        // leaving balAfter == balBefore, violating the rule.
        if (guessHash == refAnswer) {
            assertTrue(balBefore - balAfter == 2 ether);
        } else {
            // otherwise, we make no assertion about balance change (or assert it does not decrease by 2 ether,
            // but the required invariant must be universally true under reference and broken under bug.
            // Here the invariant is the implication above; for non-matching guess we simply skip,
            // but the overall test must still pass reference and fail buggy.
            // The fuzzer will find a guessHash == refAnswer where reference pays and buggy does not.
            assertTrue(true);
        }
    }
}

