pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C{value: 1 ether}();
    }

    function testFuzz_property(uint256 guessBlock, bytes32 guessHash) public {
        // Restrict guessBlock to a plausible future block number: after deployment but not too far in the past.
        // We need a block whose hash is available (at least 256 blocks old) when settle() is called,
        // but the lock-in must happen before that block. Using bound keeps the domain wide.
        uint256 deployBlock = block.number;
        vm.assume(guessBlock > deployBlock);
        vm.assume(guessBlock < deployBlock + 512);

        // Use an adversarial player as a separate EOA (the fuzzer gives an address implicitly via vm.prank).
        address player = address(0x1000);
        vm.deal(player, 1 ether);

        // Lock in the guess at the current block (which is before guessBlock).
        vm.prank(player);
        c.lockInGuess{value: 1 ether}(guessHash);

        // Warp to a block after the lock block so settle() can be called.
        // We need block.number > guessBlock, and the blockhash(guessBlock) to be available.
        // blockhash is available for the last 256 blocks. We choose a settlement block that satisfies both.
        uint256 settleBlock = guessBlock + 1;
        vm.assume(settleBlock <= guessBlock + 256);
        vm.roll(settleBlock);

        // Record balance before settle
        uint256 balanceBefore = address(c).balance;

        vm.prank(player);
        c.settle();

        uint256 balanceAfter = address(c).balance;

        // Compute the correct answer as the reference contract would:
        bytes32 correctAnswer = keccak256(abi.encodePacked(blockhash(guessBlock)));

        // Invariant: balance only decreases by exactly 2 ether when the guess matches the correct blockhash.
        // In the reference, this holds for every input; the buggy version uses a different blockhash,
        // so when guessHash matches the correct answer, balanceAfter != balanceBefore - 2 ether.
        if (guessHash == correctAnswer) {
            assertEq(balanceAfter, balanceBefore - 2 ether);
        } else {
            assertEq(balanceAfter, balanceBefore);
        }
    }
}

